"""Parses the coordinate string format used by CIMIS.

    Args:
        coord_str: Coordinate string in the format 'HMS / DD'.

    Returns:
        float: The coordinate in decimal degrees.
    """
def parse_cimis_coordinate_str(coord_str: str) -> float {
    [hms, dd] = coord_str.split('/');
    return float(dd);
}

"""
    This function is used to concat a string of words by putting underscore between words
    example: "new york steuben" --> "new_york_steuben"
    @param name: string of raw name
    @return concat_name: concated words of string by underscore
    """
def concat_name_county(name: Any) -> object {
    try {
        assert (name != "");
    } except AssertionError as exp {
        exp.args += (
            'input must not be a empty string',
            "check concat_name_county function"
        );
        raise;
    }
    name_vector = str(name).split(" ");
    concat_name = "";
    for i in name_vector {
        if (i in [" ", ""]) {
            continue;
        } else {
            concat_name = concat_name + "_" + str(i);
        }
    }
    return concat_name[1:].strip();
}

