"""
    Extract scalar reward from trial result.

    Raises
    ------
    RuntimeError
        Incorrect final result: the final result should be float/int,
        or a dict which has a key named "default" whose value is float/int.
    """
def extract_scalar_reward(value: Any, scalar_key: Any = 'default') -> object {
    if (isinstance(value, float) or isinstance(value, int)) {
        reward = value;
    } elif (
        isinstance(value, `dict)
        and (scalar_key in value)
        and isinstance(value[scalar_key], (float, int))
    ) {
        reward = value[scalar_key];
    } else {
        raise RuntimeError(
            'Incorrect final result: the final result should be float/int, or a dict which has a key named "default" whose value is float/int.'
        );
    }
    return reward;
}

"""Convert value into min & sec

    >>> int_convert_to_minute(123)
    '02:03'
    """
def int_convert_to_minute(value: Any) -> object {
    min = int((int(value) / 60));
    sec = int((int(value) % 60));
    return (("%02d" % min) + ":" + ("%02d" % sec));
}
